// Copies the pure engine files used by Edge Functions into
// supabase/functions/_shared/engine, adding the .ts import extensions Deno needs.
import fs from "node:fs";
import path from "node:path";

export const ENGINE_FILES = ["calendar.ts", "dates.ts", "presence.ts", "rotation.ts", "monthly.ts"];
const root = path.resolve(import.meta.dirname, "..");
const src = path.join(root, "lib/engine");
const dest = path.join(root, "supabase/functions/_shared/engine");

export const toDeno = (code) =>
  "// GENERATED by scripts/sync-engine.mjs from lib/engine. Do not edit.\n" +
  code.replace(/from "(\.\/[a-z-]+)"/g, 'from "$1.ts"');

if (process.argv[1] && path.resolve(process.argv[1]) === path.resolve(import.meta.filename)) {
  fs.mkdirSync(dest, { recursive: true });
  for (const f of ENGINE_FILES) {
    fs.writeFileSync(path.join(dest, f), toDeno(fs.readFileSync(path.join(src, f), "utf8")));
  }
  console.log(`Synced ${ENGINE_FILES.length} engine files to supabase/functions/_shared/engine`);
}
